import{_ as o,o as r,c as t,a2 as s}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Version 2.0.0.7 Released","description":"","frontmatter":{},"headers":[],"relativePath":"change-log/release/version-2.0.0.7-released.md","filePath":"change-log/release/version-2.0.0.7-released.md"}'),i={name:"change-log/release/version-2.0.0.7-released.md"};function n(a,e,d,c,l,p){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="version-2-0-0-7-released" tabindex="-1">Version 2.0.0.7 Released <a class="header-anchor" href="#version-2-0-0-7-released" aria-label="Permalink to &quot;Version 2.0.0.7 Released&quot;">​</a></h1><p><strong>Date: 30th Apr 2026</strong></p><p><strong>Real-Time Performance Update: WebSocket Subscribe Batching across Dhan, Fyers &amp; Upstox, Sandbox Event-Driven UI Updates, IIFL Capital Market Data Expansion &amp; Flow Editor Stability</strong></p><p>This is a stability and performance update covering <strong>26 commits</strong> since v2.0.0.6. The headline change is a unified rewrite of WebSocket subscribe handling across three major brokers (Dhan, Fyers, Upstox) instead of N per-symbol POSTs that hit broker rate limits and occasionally lost ticks for freshly-placed orders, subscriptions are now coalesced into batched grouped flushes. This closes a long-standing class of bugs reported across issues #1304 / #1314 / #1318 where ticks for newly-placed sandbox orders never reached the execution engine, manifesting as &quot;price oscillates through the trigger but the order never fires.&quot; Combined with sandbox event-driven UI updates over the existing <code>analyzer_update</code> SocketIO channel, the OrderBook / TradeBook / Positions panes now refresh the moment a fill commits.</p><hr><p><strong>Highlights</strong></p><ul><li><strong>WebSocket subscribe batching (Dhan, Fyers, Upstox)</strong> — Per-symbol subscribe POSTs are now collapsed into single grouped flushes per broker. Closes the entire class of &quot;freshly-placed order is invisible to the sandbox execution engine&quot; bugs (issues #1304, #1314, #1318).</li><li><strong>Sandbox event-driven UI updates</strong> — Engine-internal fills, auto-square-off, and T+1 settlement now emit on the existing <code>analyzer_update</code> SocketIO channel. OrderBook / TradeBook / Positions refresh automatically the moment a fill commits.</li><li><strong>IIFL Capital market data expansion</strong> — Master contract optimization plus full historical data, quotes, depth, order, and margin API support (#1309, #1319). Brings IIFL Capital up to feature parity with the other Tier-1 brokers.</li><li><strong>Fyers WebSocket overhaul</strong> — Six separate fixes: HSM subscribe batching, positional-index → <code>brsymbol</code> mapping, shared dispatcher registry across reconnects, per-symbol OI gated to FNO-only with a &gt;50-symbol skip, multiquote OI ceiling raised to 100, and index ticks fanned out to both Quote and Depth subscribers.</li><li><strong>Dhan rate-limit hardening</strong> — Minimum request interval bumped to 1.1s to stay under Dhan&#39;s &quot;Order Received N in current second exceeds Limit 10&quot; / 805 threshold.</li><li><strong>Flow Editor stability</strong> — Condition nodes honor their UI fields (and respect both <code>true/false</code> and <code>yes/no</code> edge handles), <code>&amp;#123;&amp;#123;var&amp;#125;&amp;#125;</code> interpolation supports list indexing, the Expiry node has a Futures/Options dropdown, the Config Panel scrolls on small viewports, and the Execution Log scroll is fixed.</li><li><strong>Broker symbol normalization</strong> — mstock <code>instrumenttype</code> normalized to <code>CE/PE/FUT</code> (Angel format), tradejini <code>expiry</code> stored as <code>DD-MMM-YY</code> (Zerodha format) — reduces broker-specific branching downstream (#1312).</li><li><strong>Profile page UI fix</strong> — Broker API secret no longer overflows the container or leaks the secret length through visual width.</li><li><strong>Sandbox stale-field guard</strong> — Drops <code>price</code> / <code>trigger_price</code> from order payloads based on <code>pricetype</code>, preventing leftover values from a previous order type from polluting the next placement.</li><li><strong>Option chain exchange flip</strong> — Underlying and expiry are now cleared atomically when the user flips the exchange dropdown, eliminating a transient mismatched state.</li><li><strong>CI security scan resilience</strong> — When <code>bandit</code>&#39;s SARIF formatter crashes (a known upstream bug), the security scan no longer fails the entire CI run.</li></ul><hr><p><strong>Real-Time / WebSocket</strong></p><p><strong>Dhan</strong></p><ul><li><code>1a80afb8</code> — <code>fix(dhan/ws): batch subscribes to collapse per-symbol WS messages into grouped flushes (#1314)</code></li><li><code>5aa1156f</code> — <code>fix(dhan): bump min request interval to 1.1s to avoid 805 rate limit</code></li></ul><p><strong>Fyers</strong></p><ul><li><code>671b8548</code> — <code>fix(fyers/ws): batch HSM subscribes to collapse N symbol-token POSTs into one</code></li><li><code>5eb7baaa</code> — <code>fix(fyers/ws): join HSM&lt;-&gt;Tradeboard mapping through brsymbol, not positional index</code></li><li><code>55129e6c</code> — <code>fix(fyers/ws): use shared dispatcher registry so multi-flush reconnects don&#39;t drop ticks</code></li><li><code>15c2c63b</code> — <code>fix(fyers/multiquotes): per-symbol OI for FNO only, skip when &gt;50 symbols</code></li><li><code>81cecdbd</code> — <code>fix(fyers/oi-tracker): raise multiquote OI ceiling to 100, narrow OI tracker to 47 strikes</code></li><li><code>b25bc931</code> — <code>fix(fyers/ws): fan out index ticks to both Quote and Depth subscribers</code></li></ul><p><strong>Upstox</strong></p><ul><li><code>b9e44488</code> — <code>fix(upstox/ws): batch subscribe queue, LTPC carry-forward, larger reconnect budget</code></li></ul><p>The &quot;price crosses trigger but pending sandbox order never fires&quot; pattern reported across multiple brokers is fully resolved by these batching fixes. Ticks for freshly-placed orders now reliably reach the sandbox execution engine.</p><hr><p><strong>Sandbox</strong></p><ul><li><code>3ff65a3f</code> — <code>feat(sandbox): emit analyzer_update on engine-internal fills, square-off, T+1</code></li><li><code>d3981b26</code> — <code>fix(sandbox): drop stale price/trigger fields by pricetype</code></li></ul><hr><p><strong>Brokers</strong></p><p><strong>IIFL Capital (#1309, #1319)</strong></p><ul><li><code>73857264</code> — Master contract optimization plus full market data API: historical, quotes, depth.</li><li><code>3ba5bf08</code> — Order API and margin API update.</li></ul><p><strong>mstock</strong></p><ul><li><code>df267180</code> — <code>instrumenttype</code> normalized to <code>CE/PE/FUT</code> to match Angel format.</li></ul><p><strong>tradejini</strong></p><ul><li><code>df267180</code> — Expiry stored in <code>DD-MMM-YY</code> format to match Zerodha.</li></ul><p><strong>Dhan / Fyers / Upstox</strong> — see Real-Time / WebSocket above.</p><hr><p><strong>Flow Editor</strong></p><ul><li><code>e16bb63c</code> — <code>fix(flow): condition nodes now honor their UI fields; respect both true/false and yes/no edge handles</code></li><li><code>86f67310</code> — <code>fix(flow): support list indexing in &amp;#123;&amp;#123;var&amp;#125;&amp;#125; interpolation; fix Execution Log scroll</code></li><li><code>b3d2ac11</code> — <code>fix(flow): make Config Panel scroll on small viewports</code></li><li><code>193365f2</code> — <code>feat(flow): add Futures/Options dropdown to Expiry node</code></li><li><code>5229c46e</code> — <code>docs(flow): document importer name field, fix node contracts, add 7 examples</code></li><li><code>0f4f71f0</code> — <code>docs(flow): add prompt-style JSON import reference for the Flow Editor</code></li></ul><hr><p><strong>UI / UX</strong></p><ul><li><code>92b5c877</code> — <code>fix(ui): broker API secret no longer overflows / leaks length on Profile page</code></li><li><code>975aafbc</code> — <code>fix(optionchain): clear underlying/expiry atomically on exchange flip</code></li></ul><hr><p><strong>CI / Build</strong></p><ul><li><code>3bdcd068</code> — <code>fix(ci): security scan no longer fails when bandit SARIF formatter crashes</code></li></ul><hr><p><strong>Documentation</strong></p><ul><li><code>d2baab90</code> — <code>docs(audit): add per-broker WebSocket keepalive/reconnect audit</code></li><li><code>eb46e99c</code> — <code>docs(plans): expand GTT plan&#39;s Action Center coverage</code></li><li><code>6f06329e</code> — <code>docs(claude): bump broker count from 24+ to 30+</code></li><li><code>4a3b7861</code> — <code>chore(release): bump platform version to 2.0.0.7 and document bump procedure</code> — adds a Version Bumping section to <code>CLAUDE.md</code> clarifying the platform version (<code>utils/version.py</code> + <code>pyproject.toml</code>) is independent of the Tradeboard Python SDK pin (<code>tradeboard==1.0.49</code> in <code>requirements*.txt</code> and <code>pyproject.toml</code> dependencies).</li></ul><hr><p><strong>Contributors</strong></p><ul><li><strong>@marketcalls (Rajandran)</strong> — release management, Dhan / Fyers / Upstox WebSocket subscribe-batching overhaul, sandbox event-driven UI updates, IIFL Capital market data expansion (#1309, #1319), Flow Editor stability fixes (condition nodes, list indexing, Expiry dropdown, scroll fixes), broker symbol normalization (mstock, tradejini #1312), Dhan rate-limit hardening, Profile UI fix, option chain exchange-flip atomicity, CI bandit SARIF resilience, and the per-broker WebSocket audit documentation.</li></ul><hr><p><strong>Links</strong></p><ul><li><strong>Repository</strong>: <a href="https://github.com/wesoftcorp/tradeboard-docs" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs</a></li><li><strong>Documentation</strong>: <a href="https://docs.algo.wesoftcorp.com" target="_blank" rel="noreferrer">https://docs.algo.wesoftcorp.com</a></li><li><strong>Discord</strong>: <a href="https://www.tradeboard.in/discord" target="_blank" rel="noreferrer">https://www.tradeboard.in/discord</a></li><li><strong>Issue tracker</strong>: <a href="https://github.com/wesoftcorp/tradeboard-docs/issues" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs/issues</a></li></ul><hr>',47)])])}const h=o(i,[["render",n]]);export{u as __pageData,h as default};
